153:               }
154: 
155:               if (!parcel) {
156:                 // `renderModalIntoDOM` only returns without one when it had nowhere to render it,
157:                 // which it has already reported.
158:                 closeInstance(instance);
159:                 return;
160:               }
161: 
162:               instance.parcel = parcel;
163:               modalContainer.prepend(modalFrame);
164:               // The stack decides which modal is frontmost, not the DOM order this prepend just
165:               // established: another modal opened while this one loaded belongs on top of it.
166:               applyModalVisibility(instance, frontmostModal(modalStore.getState().modalStack) === instance);
167: 
168:               // The parcel is handed back before it has mounted, so this is where the modal is
169:               // really on screen.
170:               parcel.mountPromise.then(
171:                 () => {
172:                   if (!isClosing(instance)) {
173:                     instance.state = 'MOUNTED';
174:                   }
175:                 },
176:                 (err) => {
177:                   reportError(err);
178:                   instance.parcel = null;
179:                   closeInstance(instance);
180:                 },
181:               );
182:             },
183:             (err) => {
184:               // Nothing is chained to this, so without a handler a modal that fails to load is
185:               // only an unhandled rejection — and its instance holds the overlay open over a
186:               // page the user can no longer reach.
187:               reportError(err);
