194:         // A frame is inserted as soon as the parcel exists, which is before it has mounted, so a
195:         // modal opened over one still mounting has to hide it just the same.
196:         case 'MOUNTING':
197:         case 'MOUNTED':
198:           applyModalVisibility(instance, instance === frontmost);
